int smb2_handle_write(unsigned int xid, struct cifs_io_parms *io_parms, unsigned int *nbytes,
                      struct kvec *iov, int n_vec) {
    struct smb2_write_request *req;
    struct smb2_write_response *resp;
    int rc = 0;
    int bytes_written = 0;

    req = cifs_small_req_alloc();
    if (!req) {
        return -ENOMEM;
    }

    resp = cifs_small_req_alloc();
    if (!resp) {
        cifs_small_req_free(req);
        return -ENOMEM;
    }

    req->hdr.MessageId = cpu_to_le64(xid);
    req->PersistentFileId = io_parms->persistent_fid;
    req->VolatileFileId = io_parms->volatile_fid;
    req->Offset = cpu_to_le64(io_parms->offset);
    req->DataLength = cpu_to_le32(nbytes[0]);

    rc = cifs_send_recv(io_parms->tcon->ses->server, (char *)req, iov, n_vec, CIFS_WRITE_OP,
                        (char **)&resp);
    if (rc < 0) {
        cifs_small_req_free(req);
        cifs_small_req_free(resp);
        return rc;
    }

    bytes_written = le32_to_cpu(resp->DataLength);
    *nbytes = bytes_written;

    cifs_small_req_free(req);
    cifs_small_req_free(resp);

    return 0;
}

int smb2_write(unsigned int xid, struct cifs_io_parms *io_parms, unsigned int *nbytes,
               struct kvec *iov, int n_vec)
{
    int rc = 0;
    struct smb2_write_req *req = NULL;
    struct smb2_write_rsp *rsp = NULL;
    struct cifs_ses *ses = io_parms->tcon->ses;
    struct TCP_Server_Info *server = cifs_pick_channel(io_parms->tcon);

    if (!server || !ses || (ses->need_reconnect) || (server->needs_reconnect))
        return -EIO;

    req = kzalloc(sizeof(*req) + iov[0].iov_len, GFP_KERNEL);
    if (!req)
        return -ENOMEM;

    req->hdr.PacketType = SMB2_WRITE;
    req->hdr.SessionId = ses->session_id;
    req->hdr.Channel = 0;
    req->hdr.PacketId = 0;
    req->hdr.CreditCharge = 1;
    req->StructureSize = cpu_to_le16(49);
    req->PersistentFileId = io_parms->pid;
    req->VolatileFileId = io_parms->vid;
    req->Offset = cpu_to_le64(io_parms->offset);
    req->Length = cpu_to_le32(iov[0].iov_len);
    memcpy(req + 1, iov[0].iov_base, iov[0].iov_len);

    rc = cifs_send_recv(xid, ses, (char *)req, iov, n_vec, CIFS_WRITE, &rsp);
    if (rc) {
        kfree(req);
        return rc;
    }

    *nbytes = le32_to_cpu(rsp->DataLength);
    kfree(req);
    return 0;
}

int smb2_write(unsigned int xid, struct cifs_io_parms *io_parms, unsigned int *nbytes,
               struct kvec *iov, int n_vec) {
    int rc;
    struct smb2_write_request *req;
    struct smb2_write_response *resp;
    struct TCP_Server_Info *server = io_parms->tcon->ses->server;

    if (!server) {
        return -ECONNREFUSED;
    }

    req = cifs_small_talloc(server, struct smb2_write_request);
    if (!req) {
        return -ENOMEM;
    }

    resp = cifs_small_talloc(server, struct smb2_write_response);
    if (!resp) {
        talloc_free(req);
        return -ENOMEM;
    }

    req->hdr.MessageID = cpu_to_le64(xid);
    req->PersistentFileId = cpu_to_le64(io_parms->persistent_fid);
    req->VolatileFileId = cpu_to_le64(io_parms->volatile_fid);
    req->Length = cpu_to_le32(*nbytes);
    req->Offset = cpu_to_le64(io_parms->offset);
    req->Channel = 0;
    req->RemainingBytes = 0;

    memcpy(req->Data, iov->iov_base, iov->iov_len);

    rc = cifs_send_recv(server, iov, n_vec, (char *)req, CIFS_WRITE_OP, (char **)&resp);
    if (rc < 0) {
        goto out;
    }

    *nbytes = le32_to_cpu(resp->DataLength);
    rc = 0;

out:
    talloc_free(req);
    talloc_free(resp);
    return rc;
}

int cifs_write(unsigned int xid, struct cifs_io_parms *io_parms, unsigned int *nbytes,
               struct kvec *iov, int n_vec) {
    struct smb2_write_request *req;
    struct smb2_write_response *resp;
    int rc = 0;

    if (!io_parms || !nbytes || !iov || n_vec <= 0) {
        return -EINVAL;
    }

    req = cifs_smb2_allocate_request(SMB2_WRITE);
    if (!req) {
        return -ENOMEM;
    }

    req->hdr.Id.SyncId.ProcessId = current->pid;
    req->PersistentFileId = io_parms->persistent_fid;
    req->VolatileFileId = io_parms->volatile_fid;
    req->Offset = io_parms->offset;
    req->Length = *nbytes;

    rc = cifs_smb2_set_req_signature(req, xid);
    if (rc) {
        goto out;
    }

    resp = cifs_smb2_allocate_response(SMB2_WRITE);
    if (!resp) {
        rc = -ENOMEM;
        goto out;
    }

    rc = cifs_send_recv(io_parms->tcon, xid, req, iov, n_vec, 0, (struct smb2_data **) &resp);
    if (rc) {
        goto out;
    }

    *nbytes = le32_to_cpu(resp->DataLength);
    cifs_smb2_free_response(resp);

out:
    cifs_smb2_free_request(req);
    return rc;
}

int cifs_smb2_write(unsigned int xid, struct cifs_io_parms *io_parms, unsigned int *nbytes, struct kvec *iov, int n_vec) {
    struct smb2_write_req *req;
    struct smb2_write_rsp *rsp;
    int rc = 0;
    int bytes_written = 0;

    if (!io_parms || !nbytes || !iov) {
        return -EINVAL;
    }

    req = smb2_write_init(io_parms->tcon, (unsigned int)CIFS_MAX_WRITE_SIZE, iov, n_vec);
    if (!req) {
        return -ENOMEM;
    }

    req->PersistentFileId = io_parms->pid;
    req->FileId = io_parms->fid;

    rc = cifs_send_recv(xid, io_parms->tcon->ses, (struct smb2_ioctl_req *)req, &rsp, 0);
    if (rc) {
        cifs_buf_release(req);
        return rc;
    }

    bytes_written = le32_to_cpu(rsp->DataOffset);
    if (bytes_written > 0) {
        *nbytes = bytes_written;
    } else {
        *nbytes = 0;
        cifs_buf_release(req);
        cifs_buf_release(rsp);
        return -EIO;
    }

    cifs_buf_release(rsp);
    return 0;
}
